    /**
     * @param FlatBufferBuilder $builder
     * @return int table offset
     */
    public static function endDTT(FlatBufferBuilder $builder)
    {
        $o = $builder->endObject();
        $builder->required($o, 4);  // TILESET_ID
        $builder->required($o, 34);  // PAYLOAD
        $builder->required($o, 80);  // PROVENANCE
        return $o;
    }

    public static function finishDTTBuffer(FlatBufferBuilder $builder, $offset)
    {
        $builder->finish($offset, "$DTT");
    }
